using System.Text.Json.Serialization;

namespace MatDesign.Core;

/// <summary>How binding a rule is. Stored by name ("Must"), so a file of the Studio can be read by a person.</summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum RuleLevel
{
    /// <summary>Every Mat app does this. Breaking it is a bug.</summary>
    Must,

    /// <summary>The default. Deviate only with a reason that is written down.</summary>
    Should,

    /// <summary>Allowed and recommended where it fits.</summary>
    May,
}

/// <summary>A group of rules that belong together.</summary>
public sealed record RuleArea(string Id, string Name, string Icon, string Summary);

/// <summary>
/// One rule of the design system. <see cref="Source"/> says where it comes from (the owner's own words, or the app whose documentation
/// already had it), <see cref="Check"/> whether a test of this repository enforces it or a reviewer has to.
/// </summary>
public sealed record Rule(
    string Id,
    string Area,
    string Title,
    string Statement,
    RuleLevel Level,
    string Source,
    string? Why = null,
    string? Do = null,
    string? Dont = null,
    string Check = "Review");

/// <summary>
/// The rulebook of the Mat family: every rule about how an app looks and behaves, with a stable id (<c>SHELL-03</c>) that code reviews,
/// commit messages and agents can cite. Rules that the owner stated in their own words are marked with the source "Owner".
/// </summary>
public static class RuleBook
{
    public const string Owner = "Owner";
    public const string MatSplit = "MatSplit ui-controls";
    public const string MatmonCloud = "Matmon.Cloud ui-conventions";
    public const string Matthix = "Matthix UI guide";
    public const string MatCms = "MatCMS";
    public const string MatMail = "MatMail";
    public const string Mattiverse = "Mattiverse";
    public const string MatPaper = "MatPaper";
    public const string Design = "MatDesign";

    /// <summary>The source of a rule that was written in the Studio.</summary>
    public const string Studio = "Studio";

    public static IReadOnlyList<RuleArea> Areas { get; } =
    [
        new("IDENT", "Identity", "palette", "What makes an app a Mat app and what makes it its own: the accent, the logo, the name."),
        new("SHELL", "Shell", "sidebar", "The frame around every page: menu, logo, theme button, user, version, breadcrumb."),
        new("LIST", "Lists and galleries", "list", "Toolbar, search, filter, sort, table, pagination, actions: in a fixed order."),
        new("FORM", "Forms", "edit", "Create and edit pages: fields, validation, and the buttons below the content."),
        new("BUTTON", "Buttons", "play", "Four kinds, one primary, always positive to negative."),
        new("DIALOG", "Dialogs", "message-square", "Every question and every list tool is a dialog; on a phone it is full screen."),
        new("TABLE", "Tables", "table", "Cells, numbers, status, and the card layout on a phone."),
        new("COLOR", "Colour and themes", "palette", "Tokens only, light and dark, status colours, contrast."),
        new("TYPE", "Typography", "type", "System fonts, a scale, mono for technical values."),
        new("SPACE", "Space and shape", "layers", "The 4 px scale, radii, elevation, motion."),
        new("ICON", "Icons", "star", "One sprite, inline, no font, no CDN, no emoji."),
        new("MOBILE", "Phones", "smartphone", "Mobile is not an afterthought: what changes below 900 px."),
        new("A11Y", "Accessibility", "accessibility", "Keyboard, focus, contrast, motion, labels."),
        new("CODE", "Markup and code", "code", "One code base per control, no inline styles, no outside resources."),
    ];

    public static IReadOnlyList<Rule> All { get; } =
    [
        // ------------------------------------------------------------------------------------------------ IDENT
        new("IDENT-01", "IDENT", "One colour per app",
            "Every app has its own accent colour, and it is the only colour an app chooses. It is set once, as `--mat-app-accent` on `<html data-app=\"...\">`; hover, tint, link colour and focus ring are derived from it in both modes. Everything else (layout, shapes, type, status colours) is the shared design.",
            RuleLevel.Must, Owner,
            Why: "\"Every app has its own colours, but the design is basically the same: the same identity.\"",
            Do: "<html data-app=\"matmail\">", Dont: "a second brand colour in the app's CSS", Check: "Test"),
        new("IDENT-02", "IDENT", "The accent carries its text",
            "White text on the accent reaches WCAG AA (4.5:1). If the accent is too light for that, the app sets `--mat-app-on-accent` to a dark colour instead. Dark mode lightens the accent and always uses dark text on it; that is checked for every app.",
            RuleLevel.Must, Design, Do: "darken the accent a little, or use dark text on a light accent", Check: "Test"),
        new("IDENT-03", "IDENT", "Logo and accent belong together",
            "The main colour of the app's logo is the app's accent. The logo is a rounded square (radius about 22 %) with one glyph, drawn in the flat accent colour with the glyph from the icon sprite.",
            RuleLevel.Should, Design, Why: "A user who sees the logo and then the UI should see one colour."),
        new("IDENT-04", "IDENT", "No two apps look alike",
            "Two apps do not share an accent, and no two accents are closer than the distance the palette check allows (0.45 in OKLab x 10). Look at the colour of a small logo or an active tab: if it can be mistaken for another app, it is too close.",
            RuleLevel.Should, Design, Check: "Report (Identity > Palette)"),
        new("IDENT-05", "IDENT", "The user may pick an accent",
            "An app may let a user choose their own accent from the presets (purple, indigo, ocean, teal, forest, gold, sunset, red, berry, graphite). The choice is stored per user and written as `data-accent` on `<html>`; it wins over the app colour. Components never read the accent from anywhere else.",
            RuleLevel.May, MatPaper, Why: "MatPaper, Matdo and MatMail already offer a choice; this makes it the same ten everywhere."),
        new("IDENT-06", "IDENT", "The name",
            "An app is written exactly as in the registry (MatMail, Matcad, Matddns ...), in the menu header, the browser title (`Page · App`), the manifest and the README.",
            RuleLevel.Must, Design),
        new("IDENT-07", "IDENT", "The tab title",
            "The browser title is `Page title · App name`. A detail page puts the entity first (`Invoice 2026-04 · Documents · MatPaper`).",
            RuleLevel.Should, MatPaper),

        // ------------------------------------------------------------------------------------------------- SHELL
        new("SHELL-01", "SHELL", "The menu is on the left, the logo above it",
            "The menu is always on the left. At its top is the logo with the app name; clicking it leads to the start page.",
            RuleLevel.Must, Owner, Do: "<aside class=\"mat-nav\"> brand, scroll area, foot </aside>"),
        new("SHELL-02", "SHELL", "Menu items",
            "A menu item is an icon and a label. The current page is marked (`aria-current=\"page\"`): a tint of the accent behind the whole item and the accent on its icon, never a bar at one edge (COLOR-08). Related items are grouped under short headings in sentence case. A count goes into a badge at the right end of the item.",
            RuleLevel.Should, Mattiverse),
        new("SHELL-03", "SHELL", "The foot of the menu",
            "At the bottom of the menu, in this order from top to bottom: the 3-state theme button together with the user, and below them the version. Nothing else lives down there, except the menu switcher, which an app may put directly above the user (SHELL-15).",
            RuleLevel.Must, Owner, Do: "([ menu switcher ], only where the app puts it here)\n[ user (avatar, name, role) ][ theme button ]\nversion"),
        new("SHELL-04", "SHELL", "The theme button has three states",
            "It is one icon button that cycles System, Light, Dark and shows the icon of the current state (monitor, sun, moon). Its label and tooltip name the current state and the next one. The choice is saved (per user on the server when there is an account, otherwise in the browser). System means no `data-theme` attribute: the page follows the operating system.",
            RuleLevel.Must, Owner, Check: "Test (script)"),
        new("SHELL-05", "SHELL", "The user opens a context menu",
            "The user (avatar, name, role) is a button. A click opens a context menu with the things of the account: show account, other personal settings, and Sign out as the last item. The menu opens upwards from the button and closes on Escape, on a click outside and on selecting an item.",
            RuleLevel.Must, Owner, Do: "Account · Settings · (separator) · Sign out"),
        new("SHELL-06", "SHELL", "The version is in the menu",
            "Below the user the menu shows the app name and its version in the mono font, small and muted: `MatMail 1.4.212-20261010`. Release, nightly and local builds use the version format of the project (`1.4.212-20261010`, `nightly-212-20261010`, `local-20261010`).",
            RuleLevel.Must, Owner),
        new("SHELL-07", "SHELL", "The menu scrolls on its own",
            "The menu and the content scroll separately. The page itself never scrolls; the logo and the foot of the menu stay in place while the items in between scroll.",
            RuleLevel.Must, Owner, Do: ".mat-app is as high as the window; .mat-nav__scroll and .mat-main scroll", Check: "Test (markup contract)"),
        new("SHELL-08", "SHELL", "A breadcrumb above every page",
            "The content always has a breadcrumb above it: `Section / Page / Detail`. The last item is the current page and not a link; the others lead back. A back button in the page header is not needed.",
            RuleLevel.Must, Owner, Do: "<nav class=\"mat-crumbs\"><ol>...</ol></nav>"),
        new("SHELL-09", "SHELL", "The page head",
            "Under the breadcrumb a page starts with the title (h1) and, optionally, a line of explanation. There is no icon tile next to the title. Actions do not belong in the page head: see FORM-01 and LIST-07.",
            RuleLevel.Should, Mattiverse),
        new("SHELL-10", "SHELL", "The page width",
            "Content is at most 1240 px wide and has a side padding of 16 to 32 px. Forms and reading pages use the narrow variant (780 px).",
            RuleLevel.Should, Matthix),
        new("SHELL-11", "SHELL", "Pages without a menu",
            "Sign-in, setup and error pages have no menu: a centred card on the plain page background with the logo above the title.",
            RuleLevel.Should, Design),
        new("SHELL-12", "SHELL", "Messages after a save",
            "After a successful POST the page redirects (PRG) and shows a flash message at the top of the content: a toast for \"done\", an alert for something the user has to read. Errors stay on the page, at the field and in a summary.",
            RuleLevel.Should, MatSplit),
        new("SHELL-13", "SHELL", "Submenus",
            "A menu can be hierarchical, one level deep. The parent is a button, not a page: it opens its children (`aria-expanded`, `aria-controls`). If the section has a page of its own, that page is its first child. The branch that has the current page is open when the page loads; what the user opens or closes is remembered. Children show no icon. A closed parent shows the sum of its children's badges.",
            RuleLevel.Must, Owner, Why: "Apps with many pages stay readable, and the current page is never hidden in a closed branch.", Do: "<li class=\"mat-nav__branch\"><button class=\"mat-nav__item mat-nav__parent\" data-nav-branch=\"items\" aria-expanded=\"false\">...</button><div class=\"mat-nav__sub\">...</div></li>", Dont: "a parent that is a link, a third level, a branch that hides the current page", Check: "Test (markup contract, script) and browser"),
        new("SHELL-14", "SHELL", "Badges in the menu",
            "A menu item can carry a badge at its right end: a count (above 99 it reads `99+`) or a dot for \"something new\". The tone follows the status colours (COLOR-03): the accent for a plain count, amber for something to look at, red for something that failed, green and blue for information, grey for a neutral number. A badge has a text for screen readers (\"3 invitations pending\"). The colour is never the only information (COLOR-04).",
            RuleLevel.Must, Owner, Do: "<span class=\"mat-nav__badge mat-nav__badge--warn\">3<span class=\"mat-sr-only\"> to review</span></span>", Check: "Test (markup contract) and browser"),
        new("SHELL-15", "SHELL", "More than one menu",
            "An app with distinct areas, such as an administration, has one menu per area. The switcher sits directly under the logo and shows the name of the current menu; a click opens a context menu with all menus, the current one checked. An app may put the switcher at the foot of the menu instead, directly above the user (the popup then opens upwards), or in both places; both stay in step. Choosing one swaps the items. The menu that has the current page is shown when a page loads. The switcher appears only when there are at least two menus, and a menu the user may not use is not offered. While another menu is shown, a dot on the switcher says that this one needs attention (a warning or error badge). The popup can be hierarchical, one level deep like the submenus of the items (SHELL-13): several menus can stand below a parent entry (Administration with People and System). The parent is a button that opens them (`aria-expanded`, `aria-controls`), not a menu itself; the group that has the current menu is open when a page loads; the switcher names the parent above the name of the menu; a closed parent carries the dot of the menus inside it that need attention.",
            RuleLevel.Must, Owner, Why: "An administration has its own pages, its own groups and its own badges, and does not clutter the menu of everyday work. Where the switcher sits is the app's choice: under the logo it is the first thing, above the user it is in reach of the thumb on a phone. Many menus stay readable when they are grouped.", Do: "[ logo, name ]\n[ switcher: Work v ]   (or at the foot, above the user)\nitems of the current menu\n([ switcher ])\n[ user ][ theme button ]\nversion", Dont: "a parent that is itself a menu, a third level, a switcher at the foot that opens downwards", Check: "Test (markup contract, script) and browser"),
        new("SHELL-16", "SHELL", "Long pages have an index",
            "A page with many sections, such as documentation, a long settings page or a long form, has an index beside the content (\"On this page\"): a sticky list of links to the sections, with the section in view marked, so that one click jumps there instead of many clicks through pages. From 1100 px the index is a column beside the content; below that an icon at the right end of the header bar (SHELL-17) opens the same list in a dialog (full screen on a phone), so it is in reach however far the page is scrolled. A short page needs no index.",
            RuleLevel.Should, Owner, Why: "Reading a long page and jumping around in it is faster than opening one page per section.", Do: "<div class=\"mat-with-toc\"> <div class=\"mat-with-toc__main\">...</div> <aside class=\"mat-toc-aside\"><nav class=\"mat-toc\" data-scrollspy>...</nav></aside> </div>", Check: "Test (markup contract, script) and browser"),
        new("SHELL-17", "SHELL", "Icons at the right of the header bar",
            "The bar above the content (the breadcrumb) may carry icon buttons at its right end, for things that belong to the whole app and not to one page: search, notifications, help, a language or a status. Icons only, each with a name for screen readers and a tooltip (ICON-03). A count or a dot goes in a small badge on the icon, in the colours of the status (COLOR-03). At most four; anything more goes behind one icon that opens a menu. Never actions of the page (FORM-01, LIST-07) and never the theme button or the user (SHELL-03); the one thing of a page that belongs here is its index (SHELL-16), where that is not drawn beside the content. On a phone they stay and the breadcrumb gives way.",
            RuleLevel.Should, Owner, Why: "The bar is the one place that is on every page; things of the app that the user wants at hand everywhere belong there, and page actions stay with their content.", Do: "<div class=\"mat-topbar__actions\"> icon buttons (mat-btn--ghost mat-btn--icon), a badge as the last child </div> after the breadcrumb", Dont: "text buttons, Save or Create in the bar, more than four icons, an icon without a name", Check: "Test (markup contract) and browser"),
        new("SHELL-18", "SHELL", "The footer",
            "A page may end with a footer: on the left what the app is (name, copyright, a status), on the right the links that belong to every page (imprint, privacy, help, contact). It comes after the content at the end of the scrolling area, is never fixed over the content, and lines up with the content width. On a page without a menu it sits under the card, centred. The version stays in the menu (SHELL-06); a footer is not needed on pages that are only a tool inside an app.",
            RuleLevel.Should, Owner, Why: "Legal links and contact have a fixed place that is found without searching, and the page ends instead of just stopping.", Do: "<footer class=\"mat-footer\"><p class=\"mat-footer__text\">...</p><ul class=\"mat-footer__links\">...</ul></footer>", Dont: "a footer that is fixed to the window, the theme button or the user in the footer, a second menu", Check: "Test (markup contract) and browser"),

        // -------------------------------------------------------------------------------------------------- LIST
        new("LIST-01", "LIST", "List page and edit page",
            "CRUD is a list and a separate page for creating and editing. No inline editing, no modal for create or edit. A list page may open dialogs only for its own tools (LIST-03).",
            RuleLevel.Must, Owner, Why: "Reads the same on a phone, can be linked to, and survives a reload."),
        new("LIST-02", "LIST", "The toolbar is always above",
            "Every list and every gallery has a toolbar above it, without exception. Nothing else sits between the toolbar and the list except the applied filters. A list is a collection of items the user searches, opens or edits; a table that only presents a few fixed facts (a comparison, a report of fewer than ten rows, a chart's data) is not a list and needs no toolbar.",
            RuleLevel.Must, Owner, Do: "<div class=\"mat-toolbar\"> Search, Filter, Sort ... </div>", Check: "Test (markup contract)"),
        new("LIST-03", "LIST", "Search is a button or a field; filter and sort are buttons that open dialogs",
            "In the toolbar Filter and Sort are separate buttons. Each opens a dialog with its own fields; selects, date ranges and the like are never placed in the toolbar. Search is either a third button that opens a dialog, or, where searching is the main thing to do with the list, a search field directly in the toolbar at its left, and then the dialog buttons stand together at the right end. Whatever the form, everything is sent as one GET request, so the result is a link that can be shared. On a phone the field takes the first row, the buttons stand right-aligned in the next, and the dialogs are full screen (DIALOG-03).",
            RuleLevel.Must, Owner, Why: "Searching is the most common thing to do with a list and wants a field at hand; filter and sort have several fields each and belong in a dialog.", Do: "<div class=\"mat-toolbar\"><div class=\"mat-input-icon mat-toolbar__search\">icon, input type=search</div><span class=\"mat-toolbar__spacer\"></span><div class=\"mat-toolbar__end\">Filter, Sort</div></div>", Dont: "selects or a date range directly in the toolbar, a search field and a search dialog side by side, a field in the toolbar that is not part of the GET form"),
        new("LIST-04", "LIST", "A tool in effect is visible",
            "A search, a filter or a sort that is in effect is shown on its button (highlighted, with the term, the number of filters or the sort field); a search field shows its term itself. The applied filters may also be shown as removable chips under the toolbar.",
            RuleLevel.Should, Design),
        new("LIST-05", "LIST", "The order of a list",
            "Fixed order from top to bottom: toolbar, applied chips, table or gallery, empty state, pagination, list actions. The control enforces the order, whatever the markup order.",
            RuleLevel.Must, MatSplit, Check: "Test (CSS contract)"),
        new("LIST-06", "LIST", "Pagination directly under the table",
            "Pagination sits directly under the table, and nothing else does. It renders nothing when there is one page or none. The page number is read from the query string and is never bound as a route value named `page`.",
            RuleLevel.Must, Owner),
        new("LIST-07", "LIST", "List actions below, left-aligned",
            "Actions that belong to the list as a whole (New, Import ...) stand below it, left-aligned, in one row. A destructive action keeps its distance (it is separated by the spacer).",
            RuleLevel.Must, Owner),
        new("LIST-08", "LIST", "Delete lives on the edit page",
            "Deleting is done on the edit page, not from the list. Where a row still carries a delete button (admin lists), it is the last action of the row and asks for confirmation.",
            RuleLevel.Should, MatSplit),
        new("LIST-09", "LIST", "Row actions",
            "A row opens its edit page through the title. Further actions are icon buttons with a tooltip at the end of the row (`mat-table__actions`).",
            RuleLevel.Should, Design),
        new("LIST-10", "LIST", "List or gallery",
            "Where a collection can be shown both ways, a segmented control in the toolbar switches between list and gallery. The choice is remembered per list.",
            RuleLevel.May, Design),
        new("LIST-11", "LIST", "The empty state",
            "An empty list shows an icon, a title, a sentence and the primary action that fills it. An empty result of a search says so and offers to reset the tools.",
            RuleLevel.Should, MatSplit),
        new("LIST-12", "LIST", "Counts",
            "The toolbar shows how many items the list has (and how many match, when a tool is in effect).",
            RuleLevel.May, Design),
        new("LIST-13", "LIST", "A carousel for what is looked at one after another",
            "Pictures, the steps of a tour or a few cards that are looked at one after another may be shown as a carousel: a strip of slides that scrolls and snaps, with Previous and Next buttons and one dot per page below it. Without the script it is a strip you scroll. It never moves by itself unless the author asks for it; then it has a Pause button, waits while the pointer or the focus is inside and does not start for a user who asked for less motion (A11Y-05). The region is named, every slide says which one of how many it is, the slides that are out of view cannot be reached with the Tab key, and a screen reader is told which page is shown. What people search, sort or compare is a list or a table (LIST-01), not a carousel.",
            RuleLevel.May, Design, Why: "A strip that people swipe is familiar on a phone, but a show that moves by itself, hides content behind a control that nobody finds or traps the keyboard is worse than a row of cards.", Do: "<section class=\"mat-carousel\" data-carousel aria-label=\"Tour\"><div class=\"mat-carousel__track\"><div class=\"mat-carousel__slide\">...</div></div></section>", Dont: "a show that starts by itself and cannot be paused, the one important thing on the third slide, a carousel for a list that people search", Check: "Test (markup contract, script) and browser"),
        new("LIST-15", "LIST", "Lists of rows",
            "Things that are looked at, opened, switched or ticked off one by one, as in a phone app (contacts, messages, settings, files, tasks, notifications), are a list of rows: `mat-itemlist` of `mat-item`. A row has a lead (an avatar, an icon, a thumbnail or a check), a title with up to two lines under it and an end (a note, a count, a value, the arrow). The whole row is the target (a link, a button or a label) and at least 48 px high (MOBILE-04); what has to be pressed as well (a switch, a button, a handle) stands beside it and never inside it. A state is told in more than a colour (COLOR-04): unread is bold with a dot, done is struck through, a tone has its own icon. What is selected is a tint behind the whole row (COLOR-08). Actions that appear when a row is swiped can be reached without a swipe (a More button and the arrow keys, A11Y-02) and are out of the tab order while they are hidden; a row that can be moved has a handle that works with the pointer and with the keyboard (Space, arrow keys, Escape) and says what it does to a screen reader. What people search, sort and compare in many columns is a table with a toolbar (LIST-02), not a list of rows.",
            RuleLevel.Should, Design, Why: "People know this list from their phone: one row, one target, the thing at its end tells what it does. A swipe that is the only way to an action, a switch inside a link or a state that only a colour tells is a row that some people cannot use.", Do: "<ul class=\"mat-itemlist\" data-itemlist><li class=\"mat-item\"><a class=\"mat-item__main\" href=\"#\"><span class=\"mat-item__lead\">...</span><span class=\"mat-item__body\"><span class=\"mat-item__title\">...</span></span><span class=\"mat-item__end\">...</span></a></li></ul>", Dont: "a button or a switch inside a link, actions that only a swipe reaches, a state that only a colour tells, a bar at one side of the selected row, a list of rows for a table that is searched and sorted", Check: "Test (markup contract, CSS, script) and browser"),

        // -------------------------------------------------------------------------------------------------- FORM
        new("FORM-01", "FORM", "Buttons are always under the content",
            "On every create and edit page the buttons are under the content of the form, never in the page head and never floating beside it. They stand in one row and go from positive to negative: Save, Back, then a gap, then Delete.",
            RuleLevel.Must, Owner, Do: "<div class=\"mat-btn-row\"> Save, Back, spacer, Delete </div>", Dont: "a Save button in the page head or a second, duplicate row", Check: "Test (CSS contract)"),
        new("FORM-02", "FORM", "The order is enforced by the control",
            "`mat-btn-row` orders its buttons itself: primary, then secondary and ghost, then the spacer, then danger. The order of the markup does not matter.",
            RuleLevel.Must, MatSplit, Check: "Test (CSS contract)"),
        new("FORM-03", "FORM", "Labels above, hints below, errors at the field",
            "A field has its label above, its hint below and its error message directly under it. Errors also appear as a summary at the top of the form. The space for the error line is reserved, so the layout does not jump when it appears.",
            RuleLevel.Must, Matthix),
        new("FORM-04", "FORM", "Dependent fields appear when they are needed",
            "A field that only matters for a certain answer is hidden until then (`data-show-if`, `data-show-value`). A hidden field is disabled: it posts nothing and cannot block the form.",
            RuleLevel.Must, Owner, Check: "Test (script)"),
        new("FORM-05", "FORM", "Validation in the UI, not in the browser",
            "Forms are `novalidate`; the browser's bubbles are not used. Messages are written in the language of the app and come from the model (`ErrorMessage`). Checkboxes are never \"required\".",
            RuleLevel.Must, MatSplit),
        new("FORM-06", "FORM", "Required fields",
            "Required fields are marked with an asterisk in the label; optional fields are not marked. A field is either required or says why it is optional in its hint.",
            RuleLevel.Should, MatSplit),
        new("FORM-07", "FORM", "Grid",
            "Fields use a two-column grid on a wide screen and one column on a phone. Long fields (descriptions, text areas) span both columns.",
            RuleLevel.Should, MatSplit),
        new("FORM-08", "FORM", "Every control has an id",
            "Every control has a unique id (several equal controls may share a page); labels point to it with `for`. Names are not prefixed, or model binding breaks.",
            RuleLevel.Must, MatSplit),
        new("FORM-09", "FORM", "No danger zone",
            "There is no panel or tab called \"Danger zone\". A destructive action is the last button of the button row, or it sits in the row it acts on (remove member). It keeps the red accent and asks for confirmation. A reversible switch (pause, disable) is not destructive.",
            RuleLevel.Must, MatmonCloud),
        new("FORM-10", "FORM", "Long forms",
            "On a long form the button row sticks to the bottom edge on a phone (`mat-btn-row--sticky`), so Save is always within reach.",
            RuleLevel.May, MatSplit),
        new("FORM-11", "FORM", "Confirm what cannot be undone",
            "Anything that deletes or overwrites data asks first, in a dialog that names the thing (\"Delete backup 12 Oct?\"), with the destructive button last (DIALOG-06).",
            RuleLevel.Must, MatCms),
        new("FORM-12", "FORM", "The right control for the value",
            "A field has the type of its value (`email`, `tel`, `url`, `number`, `date`, `time`, `search`, `password`) and, where it helps, `inputmode` and `autocomplete`, so that a phone shows the right keyboard and a password manager works. Up to five exclusive choices are radios, more are a select; several yes-or-no choices are checks in a group with a legend; a yes-or-no that applies at once is a switch, one that is saved with the form is a check. A range is only for a value whose exact number does not matter, and it shows the number.",
            RuleLevel.Should, Design, Do: "<input class=\"mat-input\" type=\"email\" autocomplete=\"email\">", Dont: "a text field for a date, a select with three options, a switch that needs a Save button"),
        new("FORM-13", "FORM", "Floating labels",
            "A floating label (the label in the field that moves up) may be used in a short form such as a sign-in, never in a long one. It is a real label with `for`; a placeholder is never the only label.",
            RuleLevel.May, Design, Do: "<div class=\"mat-field mat-field--float\"><input class=\"mat-input\" id=\"x\" placeholder=\" \"><label class=\"mat-label\" for=\"x\">Name</label></div>"),
        new("FORM-14", "FORM", "Form layouts",
            "The default is labels above the fields in one or two columns (three or four on a wide screen for short fields). The label beside the field is for settings pages on a wide screen and goes back above below 700 px; an inline form is for a filter or one short action in one line. A long settings page is split into sections with a heading and a sentence on the left. The buttons are under the content in every layout (FORM-01).",
            RuleLevel.Should, Design, Check: "Test (CSS contract)"),
        new("FORM-15", "FORM", "Pickers",
            "A value that the native control cannot show well is chosen in a picker: an option with a picture and a description, a date or a period, a time or a time range, a colour. The picker is a button that looks like a field and shows the value in the language of the page; the panel opens under it and, on a phone, fills the screen with an X at the top right like every dialog. The field posts one value in a fixed format (2026-10-10, 2026-10-10..2026-10-14, 09:30, 09:00..17:30, #b4235f), whatever the language. Everything can be done with the keyboard, and a picker that can be typed (time, colour) accepts typing. A native control stays the choice when it is enough. Tags are the one picker that is a field of its own: the user types, Enter or a comma makes a chip, an X or Backspace removes it, suggestions are a list under the field (also on a phone), and one value is posted, the tags joined by a comma.",
            RuleLevel.Should, MatCms, Do: "<div class=\"mat-picker\" data-picker=\"date\"><input class=\"mat-picker__input\" id=\"due\" name=\"due\" value=\"2026-10-10\"></div>", Dont: "a text field where the user types a date in a format nobody told them"),

        // ------------------------------------------------------------------------------------------------- BUTTON
        new("BUTTON-01", "BUTTON", "Four kinds",
            "There are four kinds of button: primary, secondary, ghost and danger. Nothing else: no bare `<button>`, no framework classes, no fifth style.",
            RuleLevel.Must, MatmonCloud, Check: "Test (CSS contract)"),
        new("BUTTON-02", "BUTTON", "One primary",
            "A view has one primary button: the thing most people came to do. Everything else is secondary or ghost.",
            RuleLevel.Should, Design),
        new("BUTTON-03", "BUTTON", "Labels start with a verb",
            "Button text starts with a verb and names the result: Save, Open, Verify connection. Not OK, not Submit.",
            RuleLevel.Should, Matthix),
        new("BUTTON-04", "BUTTON", "Icons",
            "Where an icon helps, it comes before the label. A button that is only an icon has an `aria-label` and a tooltip.",
            RuleLevel.Should, Owner),
        new("BUTTON-05", "BUTTON", "Size of the target",
            "Buttons and inputs are 40 px high on a mouse and 44 px on a touch screen; compact controls are 32 / 36 px. Nothing a finger has to hit is smaller than 36 px.",
            RuleLevel.Must, Matthix, Check: "Test (tokens)"),
        new("BUTTON-06", "BUTTON", "Links and buttons",
            "A button does something, a link goes somewhere. A link that looks like a button (`<a class=\"mat-btn\">`) is fine for navigation; a link never submits.",
            RuleLevel.Should, Design),

        // ------------------------------------------------------------------------------------------------- DIALOG
        new("DIALOG-01", "DIALOG", "Everything is a dialog",
            "Confirmations, notices and inputs are always shown as a dialog of the toolkit: `MatUi.confirm`, `MatUi.alert`, `MatUi.prompt`, or `data-confirm` on a button, link or form. `window.confirm`, `alert` and `prompt` are never used.",
            RuleLevel.Must, Owner, Do: "<button data-confirm=\"Delete this backup?\">", Dont: "onsubmit=\"return confirm(...)\"", Check: "Test (script contract)"),
        new("DIALOG-02", "DIALOG", "The tools of a list are dialogs",
            "Search, filter and sort of a list open dialogs (LIST-03). Their buttons stand under the fields: Apply, Cancel, then a gap and Reset.",
            RuleLevel.Must, Owner),
        new("DIALOG-03", "DIALOG", "On a phone every dialog is full screen",
            "Below 640 px every dialog fills the screen. The close button (X) is at the top right of the head. The dialog respects the safe areas of the device.",
            RuleLevel.Must, Owner, Check: "Test (CSS contract)"),
        new("DIALOG-04", "DIALOG", "Structure",
            "A dialog has a head (title and X), a body that scrolls on its own, and a foot with the buttons under the content, positive to negative.",
            RuleLevel.Must, Owner),
        new("DIALOG-05", "DIALOG", "Behaviour",
            "Escape closes a dialog, a click outside closes one that is not a data-entry form, focus moves into the dialog when it opens and back to the opener when it closes, and the page behind does not scroll.",
            RuleLevel.Must, Design),
        new("DIALOG-06", "DIALOG", "Destructive confirmation",
            "When the confirmation is for something destructive, Cancel comes first and the destructive action is the last button, in the solid danger style. Otherwise the confirming button comes first.",
            RuleLevel.Must, Owner),
        new("DIALOG-07", "DIALOG", "Menus and dropdowns on a phone",
            "A custom dropdown or selection list that would not fit on a small screen becomes a full-screen sheet there, like a dialog. A context menu with a few items stays a small popover.",
            RuleLevel.Should, MatMail),

        // -------------------------------------------------------------------------------------------------- TABLE
        new("TABLE-01", "TABLE", "Numbers and technical values",
            "Numbers are right-aligned with tabular figures. IDs, IP addresses, versions, ports and timestamps use the mono font.",
            RuleLevel.Should, Matthix),
        new("TABLE-02", "TABLE", "Every cell has a label",
            "Every `<td>` has `data-label` with the name of its column. Below 720 px a row becomes a card and the label is drawn in front of the value.",
            RuleLevel.Must, MatSplit, Check: "Test (CSS contract)"),
        new("TABLE-03", "TABLE", "Status is a pill with text",
            "A state is shown as a pill with a dot and a word (Online, Warning, Offline, Unknown). Colour alone never carries the information.",
            RuleLevel.Must, Matthix),
        new("TABLE-04", "TABLE", "Wide tables",
            "A table that cannot become cards scrolls horizontally inside its own container and shows that it does.",
            RuleLevel.Should, Matthix),

        // -------------------------------------------------------------------------------------------------- COLOR
        new("COLOR-01", "COLOR", "Tokens only",
            "Colours come from the tokens (`var(--mat-...)`), never as a literal in an app's CSS. A hard-coded white or grey is a bug that shows up as a bright block in dark mode.",
            RuleLevel.Must, MatCms, Check: "Test (toolkit CSS)"),
        new("COLOR-02", "COLOR", "Light and dark",
            "Every app works in light and dark, and follows the system by default. The dark set exists for every colour token; the two places it is written (explicit `data-theme=\"dark\"` and system) are identical.",
            RuleLevel.Must, Owner, Check: "Test"),
        new("COLOR-03", "COLOR", "Status colours have a meaning",
            "Green is success and healthy, amber is attention, red is an error or a destructive action, blue is information. The accent is never used for one of these meanings.",
            RuleLevel.Must, Matthix),
        new("COLOR-04", "COLOR", "Colour is never the only information",
            "Anything that colour tells (state, importance, selection) is also told by text or an icon.",
            RuleLevel.Must, Matthix),
        new("COLOR-05", "COLOR", "Contrast",
            "Text reaches WCAG AA: 4.5:1 for body text, 3:1 for large text and for the borders of controls. Muted text still passes; faint text is only for placeholders and disabled states.",
            RuleLevel.Must, Matthix, Check: "Test"),
        new("COLOR-06", "COLOR", "Flat surfaces",
            "Surfaces are plain colours, and so are the logo tile and the avatar (the flat accent). No gradient backgrounds, no glow around a button or a logo, no blur behind a bar or a dialog. A gradient is only for data, such as the colour ramps of the colour picker.",
            RuleLevel.Should, Design),
        new("COLOR-07", "COLOR", "Previews stay as they are",
            "Content that shows something from outside (an e-mail body, a document preview, a QR code) stays white in dark mode on purpose.",
            RuleLevel.Should, MatCms),
        new("COLOR-08", "COLOR", "Selected is a tint, not a bar on one side",
            "What is selected or current (a menu item, an entry of the index, a tab, a row) is shown by a tint of the accent behind the whole item, a stronger weight and the accent on its icon. Never by a coloured bar or border on one side of a rounded item: it looks generated and it breaks at the corners. A line under tabs is the one exception, because it is the underline of the tab row, and then the tab has square corners.",
            RuleLevel.Should, Design, Why: "A bar at one edge of a rounded shape has no clean corner and is what every generated interface does.", Do: ".mat-nav__item[aria-current=\"page\"] { background: var(--mat-accent-soft-strong); }", Dont: "border-left: 3px solid var(--mat-accent) on a rounded item, an inset shadow at one side, a ::before bar", Check: "Test (toolkit CSS)"),

        // --------------------------------------------------------------------------------------------------- TYPE
        new("TYPE-01", "TYPE", "System fonts",
            "Apps use the system font stack and the system mono stack. No web fonts: apps must work offline and as a PWA.",
            RuleLevel.Must, MatSplit, Check: "Test (toolkit CSS)"),
        new("TYPE-02", "TYPE", "The scale",
            "Type sizes come from the scale (12, 13, 15, 17, 20, 26, 34 px). Body text is 15 px, table text 13 px, the page title 26 px.",
            RuleLevel.Should, Design),
        new("TYPE-03", "TYPE", "Mono for technical values",
            "IDs, versions, hashes, ports, paths and code are set in mono. Labels and technical values in the same row are not mixed in one font.",
            RuleLevel.Should, Matthix),
        new("TYPE-04", "TYPE", "Line length",
            "Running text is at most about 70 characters wide.",
            RuleLevel.Should, Matthix),

        // --------------------------------------------------------------------------------------------------- SPACE
        new("SPACE-01", "SPACE", "The 4 px scale",
            "Gaps and paddings come from the scale (4, 8, 12, 16, 20, 24, 32, 40, 48 px).",
            RuleLevel.Should, Design),
        new("SPACE-02", "SPACE", "Radii",
            "Cards and dialogs use the large radius (8 px), buttons, inputs and menu items 6 px, small marks 3 or 4 px. Only badges, status pills and switches are round. Do not invent a radius.",
            RuleLevel.Should, Matthix),
        new("SPACE-03", "SPACE", "Elevation",
            "A card is a surface with a line and hardly a shadow; popovers carry the middle shadow, dialogs the large one. Lines and surfaces structure more than shadows do, and nothing lifts on hover.",
            RuleLevel.Should, Matthix),
        new("SPACE-04", "SPACE", "Motion",
            "Motion is short and has a purpose: 120 ms for hover and press, 180 ms for menus and tabs, 280 ms for dialogs and the drawer, one easing curve. With `prefers-reduced-motion` everything that is not needed stops.",
            RuleLevel.Must, Matthix, Check: "Test (toolkit CSS)"),
        new("SPACE-05", "SPACE", "Scrollbars appear while scrolling",
            "Scrollbars are invisible until something scrolls and fade out about a second after. On a touch screen the system's overlay scrollbars apply.",
            RuleLevel.Must, Owner, Check: "Test (script)"),

        // ---------------------------------------------------------------------------------------------------- ICON
        new("ICON-01", "ICON", "One sprite, inline",
            "Icons are inline SVG from the toolkit sprite: 24 px grid, 2 px stroke, round caps, `currentColor`. No icon font, no icon CDN, no image icons, no emoji in the interface.",
            RuleLevel.Must, MatSplit, Why: "Works offline, follows the theme and the text size.", Check: "Test (sprite)"),
        new("ICON-02", "ICON", "Same meaning, same icon",
            "A meaning has one icon everywhere: save, edit, trash, search, filter, sort, back, settings, user ... (see the icon list). Icons are used where they help, not on everything.",
            RuleLevel.Must, Owner),
        new("ICON-03", "ICON", "Icon only with a name",
            "An icon without a visible label has an accessible name (`aria-label`) and, on a pointer device, a tooltip.",
            RuleLevel.Must, Design),
        new("ICON-04", "ICON", "App logos",
            "Every app has a logo for the menu (a tile with a glyph, IDENT-03), a favicon (SVG) and the PWA icons (192, 512 and a maskable 512).",
            RuleLevel.Should, Design),
        new("ICON-05", "ICON", "More icons are optional",
            "The sprite of the toolkit stays small: the icons the apps use. An app that needs more takes them from the icon library, which is made of files of its own (`matui-iconlib.svg`, `iconlib.json` and each icon as a single .svg), sorted into categories where an icon can be in several. The library is not part of `matui.css` and nothing in the toolkit depends on it, so an app can do without it, and it never becomes part of the sprite as a whole. Its icons follow ICON-01 to ICON-03 like the others, and one that gets a meaning in the interface is moved into the sprite (ICON-02: one meaning, one icon).",
            RuleLevel.Should, Owner, Why: "A smart home needs two hundred icons and most apps twenty: an app takes what it needs and the toolkit stays small.", Check: "Test (library)"),

        // -------------------------------------------------------------------------------------------------- MOBILE
        new("MOBILE-01", "MOBILE", "Phones are first-class",
            "Every page is designed and checked at 390 px wide, not only at desktop width. Nothing scrolls sideways.",
            RuleLevel.Must, Owner),
        new("MOBILE-02", "MOBILE", "What changes below 900 px",
            "The menu becomes a drawer behind a burger button in the top bar; the breadcrumb shows its last two items; two- and three-column grids become one column; secondary table columns can be hidden (`mat-hide-sm`).",
            RuleLevel.Must, Design),
        new("MOBILE-03", "MOBILE", "Dialogs and tables",
            "Dialogs are full screen (DIALOG-03), tables become cards (TABLE-02).",
            RuleLevel.Must, Owner),
        new("MOBILE-04", "MOBILE", "Touch",
            "Targets are at least 44 px (36 px for compact controls), there is no information that only a hover shows, and the safe areas of notches and home indicators are respected.",
            RuleLevel.Must, Matthix),
        new("MOBILE-05", "MOBILE", "Installable",
            "An app that people use daily is a PWA: manifest, `theme-color`, icons and a service worker that caches the shell.",
            RuleLevel.May, MatMail),

        // --------------------------------------------------------------------------------------------------- A11Y
        new("A11Y-01", "A11Y", "Focus",
            "Every interactive element shows a visible focus ring from the accent. Focus is never removed without a replacement. The first focusable element is the skip link.",
            RuleLevel.Must, Matthix, Check: "Test (toolkit CSS)"),
        new("A11Y-02", "A11Y", "Keyboard",
            "Everything can be done with the keyboard: menus (arrow keys), tabs (arrow keys, Home, End), dialogs (Escape, focus trap), the search dialog with `/`.",
            RuleLevel.Must, Design),
        new("A11Y-03", "A11Y", "Landmarks and names",
            "A page has `nav` for the menu (labelled), `main` for the content and `nav aria-label=\"Breadcrumb\"` for the breadcrumb. Controls have labels; the current page is `aria-current=\"page\"`.",
            RuleLevel.Must, Matthix, Check: "Test (markup contract)"),
        new("A11Y-04", "A11Y", "Errors are announced",
            "A form error is written next to the field, linked with `aria-invalid`, and summarised at the top.",
            RuleLevel.Should, Matthix),
        new("A11Y-05", "A11Y", "Reduced motion",
            "With `prefers-reduced-motion` animations and transitions are reduced to nothing (SPACE-04).",
            RuleLevel.Must, Matthix, Check: "Test (toolkit CSS)"),

        // --------------------------------------------------------------------------------------------------- CODE
        new("CODE-01", "CODE", "One code base per control",
            "Table, pagination, toolbar, form, field, tabs, dialog and button each have one implementation, shared by every page. Several equal controls may share a page (unique ids).",
            RuleLevel.Must, Owner),
        new("CODE-02", "CODE", "Nothing outside the toolkit",
            "A page is built only from the toolkit's classes. No inline styles, no inline scripts, no new class for something the toolkit already ships. An app's own classes carry the app's prefix.",
            RuleLevel.Must, MatmonCloud),
        new("CODE-03", "CODE", "No outside resources",
            "No external fonts, icons, scripts or stylesheets: the app works offline and under a strict content security policy.",
            RuleLevel.Must, MatSplit, Check: "Test (toolkit)"),
        new("CODE-04", "CODE", "Names",
            "Toolkit classes start with `mat-`, custom properties with `--mat-`, data-attributes of behaviour are named after what they do (`data-confirm`, `data-show-if`). Block, element and modifier: `mat-card__head`, `mat-btn--primary`.",
            RuleLevel.Must, Design, Check: "Test (toolkit CSS)"),
        new("CODE-05", "CODE", "Language",
            "Code, identifiers and comments are English; the text of the interface is in the language of the app, with translated validation messages.",
            RuleLevel.Should, MatCms),
        new("CODE-06", "CODE", "Controls render nothing when there is nothing to show",
            "A pagination with one page, an empty alert, a toolbar without tools render no markup at all.",
            RuleLevel.Should, MatSplit),
        new("CODE-07", "CODE", "The documentation shows the code with the example",
            "Every example of the documentation (the components, the layout, the utilities and the styleguide of a release) shows its code with it, never behind a click: beside the example where the window is wide, below it otherwise, and below it for an example that needs the whole width (a table, a bar, a grid). The code is the markup that is drawn, from one source, coloured, with a Copy button; under the title the classes and the data attributes that the examples use are named.",
            RuleLevel.Should, Design, Why: "A developer copies what they see. Code that is one click away is not looked at, and code that is typed next to a picture drifts from it.", Do: "<div class=\"doc-example__body\"><div class=\"doc-example__live\">the example</div><div class=\"doc-code\">HTML | Copy, the code</div></div>", Dont: "a Markup disclosure, a screenshot instead of a live example, code that is written by hand next to the picture", Check: "Test (the page of the code is the code of the example) and browser"),
        new("CODE-08", "CODE", "A group of components is shown in a real page",
            "Beside its components the documentation shows each group in a real page of a sample app, opened when it is wanted: the controls are judged where they are used and not only on their own. The page can be a desktop window or a phone, can be opened by itself, and a component that the page uses can be outlined in it.",
            RuleLevel.Should, Design, Why: "A button that looks right alone can be wrong in a form; seeing the group in a page is how the spacing, the order and the neighbours are judged.", Do: "<details class=\"doc-context\"> a frame of /Preview with the marks of the components in it </details>", Dont: "a mock-up that is drawn by hand and can differ from the toolkit, a frame that loads before it is opened", Check: "Test (every mark finds its component in the page) and browser"),
    ];

    public static Rule? Get(string id) => All.FirstOrDefault(r => r.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public static IEnumerable<Rule> In(string areaId) => All.Where(r => r.Area == areaId);
}
